// Calculate the total
export function totalCents(lines) {
  // Initialize the total
  let total = 0;
  // Loop through each line
  for (const line of lines) {
    // Add price times quantity
    total += line.priceCents * line.quantity;
  }
  // Return the result
  return total;
}
function unusedEnhancedTotalV2(lines) { return totalCents(lines); }
